import type Realm from "realm";
import Taxon from "realmModels/Taxon";
import type { RealmTaxon } from "realmModels/types";
import safeRealmWrite from "sharedHelpers/safeRealmWrite";

// [id, name, preferred_common_name, rank, rank_level, ancestor_ids, codes],
// generated by scripts/buildBirdCodes.py from the Institute for Bird
// Populations' official 4-letter alpha code list
type BirdCodeEntry = [number, string, string | null, string, number, number[], string[]];

// Stores every official 4-letter bird code on its taxon so offline search
// finds birds by code, creating the taxa that aren't cached yet
const loadBirdCodes = ( realm: Realm ) => {
  // Required here so the 290 KB list is only parsed when this runs, at idle
  // time after launch
  // eslint-disable-next-line global-require
  const entries = require( "appConstants/birdCodes.json" ) as BirdCodeEntry[];
  const loadedCount = realm.objects( "Taxon" ).filtered( "birdCodes.@count > 0" ).length;
  if ( loadedCount === entries.length ) return;
  safeRealmWrite( realm, ( ) => {
    entries.forEach( ( [id, name, commonName, rank, rankLevel, ancestorIds, codes] ) => {
      const taxon = realm.objectForPrimaryKey<RealmTaxon>( "Taxon", id );
      if ( taxon ) {
        if ( Array.from( taxon.birdCodes || [] ).join( ) !== codes.join( ) ) {
          taxon.birdCodes = codes;
        }
        return;
      }
      const newTaxon = {
        id,
        name,
        preferred_common_name: commonName,
        rank,
        rank_level: rankLevel,
        ancestor_ids: ancestorIds,
        iconic_taxon_name: "Aves",
        birdCodes: codes,
      };
      realm.create( "Taxon", {
        ...newTaxon,
        _searchableName: Taxon.compileSearchableName( newTaxon ),
      } );
    } );
  }, "loading bird codes" );
};

export default loadBirdCodes;
